import { docsLoader, i18nLoader } from '@astrojs/starlight/loaders';
import { docsSchema, i18nSchema } from '@astrojs/starlight/schema';
import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';

export const collections = {
  // Generated by scripts/sync-content.mjs; see docs-src/.
  docs: defineCollection({
    loader: docsLoader(),
    schema: docsSchema({
      // What a search result shows, where the page's own title or description is not it
      // (src/routeData.ts; docs/rfc/0005-search.md 1.2). The h1, sidebar label and lede stay.
      extend: z.object({
        /** The <title>, at most 65 characters, written for searchers; used as it is. */
        seoTitle: z.string().max(65).optional(),
        /** The meta description, when the frontmatter one is longer than a result shows. */
        seoDescription: z.string().min(70).max(160).optional(),
        /** An image in public/og/ by name, instead of og/docs.png. */
        ogImage: z.string().regex(/^[a-z0-9-]+$/).optional(),
      }),
    }),
  }),
  // Starlight always reads this collection. en.json restates one default label so it is not
  // empty, which would make every build warn.
  i18n: defineCollection({ loader: i18nLoader(), schema: i18nSchema() }),
};
